message.content:
{
  "gate_token": "3jq_fMnN2uAZ0SSoeaTIOw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map at the city's broken edge.",
      "visual_description": "Dusk over a ruined royal city; a cloaked figure spreads a parchment map on a cracked stone slab, brass compass glinting.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "A small oil lamp held aloft, its single flame-eye narrowed toward distant castle gates draped in tattered royal banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the rubble-strewn avenue.",
      "visual_description": "A clockwork fox with blue glass eyes darts between fallen pillars, its key-wind tail ticking in moonlight.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet steps out of a broken pane as if from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath the cursed tower.",
      "visual_description": "Four companions huddle at the base of a leaning black tower wrapped in violet vapor; the lamp's eye glows steady.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "They find an official asleep on a ledger.",
      "visual_description": "A plump figure snores at a toppled desk, ledger book under his cheek, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox tugs at the dozing official's coat.",
      "visual_description": "Clockwork fox bites a sleeve hem; papers flutter; the official mumbles without waking.",
      "characters": ["tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 8,
      "caption": "The lamp recites a rumor of winged fire.",
      "visual_description": "Oracle lamp casts a flickering mural on a wall: silhouetted wings circling a smoking spire over the ruined skyline.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "An armored patrol marches past the alley.",
      "visual_description": "From a shadowed nook, the team watches polished helms and pikes file by under a torn banner; Tin Fox crouches silent.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara charts a path through magic doors.",
      "visual_description": "She traces a glowing route across her map; behind her, three doors hover in midair, each humming a different color.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver slips through a mirrored door.",
      "visual_description": "The diver pushes into a silver door as if into still water, ripples spreading; the lamp peers in behind.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, frightened faces press against glass.",
      "visual_description": "On the far side of a vast mirror, dim figures huddle; Glass Diver places a gloved hand to the surface in greeting.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox finds the captive in the throne hall.",
      "visual_description": "A clockwork fox bounds across a moonlit marble floor toward a bound figure slumped beneath a cracked throne.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle Lamp warns of a closing trap.",
      "visual_description": "Lamp's flame-eye flares red; behind the team, stone teeth begin to descend across an archway.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Glass Diver pulls the captive through a window.",
      "visual_description": "The diver hauls a limp figure up through a tall stained-glass window that ripples like a pond.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They drag the dozing official along anyway.",
      "visual_description": "Mara and Tin Fox haul the still-snoring official by the ankles down a rubble staircase, ledger bouncing behind.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The escape begins across a trembling bridge.",
      "visual_description": "A long stone bridge stretches over a chasm of glowing mist; the team runs as cables snap behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the city, the lamp's eye finally dims.",
      "visual_description": "On a green hillside at dawn, the companions rest; the oracle lamp's flame softens, Tin Fox curls beside Mara's boot.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

